from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    seen = set()
    objects = []
    fixed = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or color == 8 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x, color))
                for dy, dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    yy, xx = y+dy, x+dx
                    if 0 <= yy < h and 0 <= xx < w and (yy,xx) not in seen and grid[yy][xx] == color:
                        seen.add((yy,xx)); q.append((yy,xx))
            objects.append(cells)
    # Settle rightmost objects first; each rigid component slides right until blocked.
    objects.sort(key=lambda obj: max(c for r,c,col in obj), reverse=True)
    occupied = set(fixed)
    out = [[0]*w for _ in range(h)]
    for r, c in fixed:
        out[r][c] = 8
    for obj in objects:
        delta = 0
        while True:
            step = delta + 1
            if any(c+step >= w or (r,c+step) in occupied for r,c,col in obj):
                break
            delta = step
        for r,c,col in obj:
            nc = c + delta
            out[r][nc] = col
            occupied.add((r,nc))
    return out
